package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionLengthStoriesTest {
 @Test public void all649ConditionsUsePublicStoryAndStudentRelations(){for(String id:List.of(FractionLengthStories.ADD,FractionLengthStories.SUB)){int count=0;for(int d=2;d<=12;d++)for(int a=1;a<=d;a++)for(int b=1;b<=d;b++)if(id.equals(FractionLengthStories.ADD)?a+b<=d:b<=a){Question q=FractionLengthStories.make(id,d,a,b);int answer=id.equals(FractionLengthStories.ADD)?a+b:a-b;q.answers=new String[]{"999"};q.expression="999";assertTrue(new Checker().check(q,List.of(),List.of(answer+"/"+d)).correct());assertTrue(new Checker().check(q,List.of(),List.of((answer*2)+"/"+(d*2))).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of((answer+1)+"/"+d)).status);assertEquals(1,FractionInput.errorPart(q,(answer+1)+"/"+d));assertEquals(1,FractionInput.errorPart(q,(answer*2+1)+"/"+(d*2)));assertEquals(0,FractionInput.errorPart(q,(answer*2)+"/"+(d*2)));HelpPlan p=HelpPlan.forQuestion(q);assertEquals(4,p.size());assertFalse(p.canTransfer());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] inputs={d,a,b,answer};for(int i=0;i<4;i++)assertTrue(p.step(i).accepts(""+inputs[i]));count++;}assertEquals(id.equals(FractionLengthStories.ADD)?286:363,count);}}
 @Test public void realGradeThreeSupplyExhaustsBeforeOldest(){for(String id:List.of(FractionLengthStories.ADD,FractionLengthStories.SUB)){Generator g=new Generator(new Random(140));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",id,3);int size=id.equals(FractionLengthStories.ADD)?286:363;List<String> recent=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<size;i++){Question q=g.next(id,recent,false,limits);assertNotNull(FractionLengthStories.read(q));assertTrue(seen.add(q.signature()));assertTrue(q.choices.isEmpty());recent.add(q.signature());}assertEquals(recent.get(0),g.next(id,recent,false,limits).signature());}}
 @Test public void malformedAndOutOfWholeContextsCannotUseKeys(){for(String prompt:List.of(String.format(FractionLengthStories.template(FractionLengthStories.ADD),2,3,2,3),String.format(FractionLengthStories.template(FractionLengthStories.SUB),1,3,2,3),String.format(FractionLengthStories.template(FractionLengthStories.SUB),1,3,1,4),String.format(FractionLengthStories.template(FractionLengthStories.ADD),1,13,1,13),"unknown")){Question q=new Question(prompt.contains("남은")?FractionLengthStories.SUB:FractionLengthStories.ADD,prompt,"0","0");assertNull(FractionLengthStories.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}}
}
